     1→/**
     2→ * FreeLang v4 StdLib — JSON Functions (3개 + 확장)
     3→ *
     4→ * 1. json_parse(s)              → ok(Value) | err(msg)
     5→ *    - JSON 문자열 → FreeLang Value
     6→ *    - object → struct, array → arr, string → str, number → i32/f64, bool → bool
     7→ *
     8→ * 2. json_stringify(v)          → str
     9→ *    - FreeLang Value → JSON 문자열
    10→ *
    11→ * 3. json_validate(s, schema)   → bool
    12→ *    - JSON 스키마 기반 검증
    13→ *    - schema: { type, required?, properties? }
    14→ *
    15→ * + json_pretty(v)              → str   (들여쓰기 2칸)
    16→ * + json_get(v, path)           → some(Value) | none   (점 경로 접근)
    17→ * + json_merge(a, b)            → ok(Value) | err
    18→ */
    19→
    20→import { Value, V, assertStr } from "./types";
    21→
    22→// ============================================================
    23→// JSON → Value 변환
    24→// ============================================================
    25→
    26→function jsToValue(js: unknown): Value {
    27→  if (js === null)              return V.none();
    28→  if (typeof js === "boolean")  return V.bool(js);
    29→  if (typeof js === "string")   return V.str(js);
    30→  if (typeof js === "number") {
    31→    return Number.isInteger(js) ? V.i32(js) : V.f64(js);
    32→  }
    33→  if (Array.isArray(js)) {
    34→    return V.arr(js.map(jsToValue));
    35→  }
    36→  if (typeof js === "object") {
    37→    const fields = new Map<string, Value>();
    38→    for (const [k, v] of Object.entries(js as Record<string, unknown>)) {
    39→      fields.set(k, jsToValue(v));
    40→    }
    41→    return { tag: "struct", fields };
    42→  }
    43→  return V.none();
    44→}
    45→
    46→// ============================================================
    47→// Value → JS 변환
    48→// ============================================================
    49→
    50→function valueToJs(v: Value): unknown {
    51→  switch (v.tag) {
    52→    case "i32":
    53→    case "f64":    return v.val;
    54→    case "str":    return v.val;
    55→    case "bool":   return v.val;
    56→    case "arr":    return (v as Extract<Value, { tag: "arr" }>).elements.map(valueToJs);
    57→    case "struct": {
    58→      const obj: Record<string, unknown> = {};
    59→      for (const [k, val] of (v as Extract<Value, { tag: "struct" }>).fields) {
    60→        obj[k] = valueToJs(val);

