   363→    // stats: 벡터 배열 통계 정보
   364→    func (va: *Vector3DArray) stats() -> VectorStats {
   365→        let memory_bytes = u64(len(va.x_data) * 4) +
   366→                          u64(len(va.y_data) * 4) +
   367→                          u64(len(va.z_data) * 4);
   368→
   369→        let cache_lines = (u32(memory_bytes) / CACHE_LINE_SIZE) + 1;
   370→
   371→        return VectorStats {
   372→            count: va.count,
   373→            capacity: va.capacity,
   374→            memory_bytes: memory_bytes,
   375→            cache_lines: cache_lines * 3,
   376→            simd_ops_per_cycle: SIMD_LANE_COUNT,
   377→        };
   378→    }
