     1→// ============================================================================
     2→// Benchmark Framework (벤치마크 프레임워크)
     3→// FreeLang 구현 - SoA vs AoS 성능 비교, 자동 측정
     4→// ============================================================================
     5→//
     6→// 목표: Zero-Copy DB 성능을 정량적으로 측정하고
     7→//       SoA 레이아웃과 기존 AoS 레이아웃의 성능 차이를 입증
     8→//
     9→// 메트릭:
    10→//   - Throughput (처리량): ops/sec
    11→//   - Latency (지연시간): microseconds per operation
    12→//   - Memory Usage (메모리 사용량): bytes
    13→//   - Cache Efficiency (캐시 효율): cache line misses
    14→//   - SIMD Utilization (SIMD 활용도): percentage
    15→//
    16→// 구조:
    17→//   1. Timer: 정밀한 시간 측정
    18→//   2. Memory Profiler: 메모리 할당 추적
    19→//   3. Benchmark Harness: 테스트 실행 및 통계
    20→//   4. Performance Report: 결과 리포트
    21→// ============================================================================
    22→
    23→module benchmark {
    24→    // ========================================================================
    25→    // 상수
    26→    // ========================================================================
    27→
    28→    const NANO_PER_MICRO: u64 = 1000;
    29→    const MICRO_PER_MILLI: u64 = 1000;
    30→    const MILLI_PER_SEC: u64 = 1000;
    31→
    32→    const CACHE_LINE_SIZE: u64 = 64;
    33→    const L1_CACHE_SIZE: u64 = 32000;    // 32 KB (typical)
    34→    const L2_CACHE_SIZE: u64 = 262144;   // 256 KB
    35→
    36→    // ========================================================================
    37→    // 데이터 구조
    38→    // ========================================================================
    39→
    40→    // Timer는 정밀한 시간 측정
    41→    struct Timer {
    42→        start_time: u64;        // 시작 시간 (nanoseconds)
    43→        end_time: u64;          // 종료 시간
    44→        elapsed: u64;           // 경과 시간
    45→    }
    46→
    47→    // MemoryMetric은 메모리 사용량 메트릭
    48→    struct MemoryMetric {
    49→        allocated_bytes: u64;
    50→        peak_bytes: u64;
    51→        freed_bytes: u64;
    52→        allocations_count: u32;
    53→    }
    54→
    55→    // PerformanceMetric은 단일 벤치마크 실행 결과
    56→    struct PerformanceMetric {
    57→        name: string;
    58→        iterations: u64;
    59→        elapsed_time: u64;      // microseconds
    60→        throughput: f32;        // ops/sec
    61→        latency: f32;           // microseconds/op
    62→        memory_used: u64;       // bytes
    63→        cache_lines: u64;
    64→        is_soa: bool;
    65→    }
    66→
    67→    // BenchmarkReport는 전체 벤치마크 리포트
    68→    struct BenchmarkReport {
    69→        test_name: string;
    70→        timestamp: string;
    71→        metrics: [PerformanceMetric];
    72→        summary_stats: BenchmarkStats;
    73→    }
    74→
    75→    // BenchmarkStats는 통계 정보
    76→    struct BenchmarkStats {
    77→        total_ops: u64;
    78→        total_time: u64;        // microseconds
    79→        avg_throughput: f32;
    80→        best_throughput: f32;
    81→        worst_throughput: f32;
    82→        memory_overhead: f32;   // percentage
    83→    }
    84→
    85→    // ========================================================================
    86→    // Timer 함수
    87→    // ========================================================================
    88→
    89→    // timer_start: 타이머 시작
    90→    func timer_start() -> Timer {
    91→        // 실제 구현에서는 system time 호출
    92→        return Timer {
    93→            start_time: 0,  // placeholder
    94→            end_time: 0,
    95→            elapsed: 0,
    96→        };
    97→    }
    98→
    99→    // timer_stop: 타이머 정지 및 경과 시간 계산
   100→    func (t: *Timer) timer_stop() -> u64 {
   101→        // 실제 구현에서는 system time 호출
   102→        t.end_time = 0;  // placeholder
   103→        t.elapsed = t.end_time - t.start_time;
   104→        return t.elapsed;
   105→    }
   106→
   107→    // ========================================================================
   108→    // SoA 벤치마크 (최적화된 구현)
   109→    // ========================================================================
   110→
   111→    // 구조: Structure of Arrays
   112→    struct Vector3DSoA {
   113→        x: [f32];
   114→        y: [f32];
   115→        z: [f32];
   116→        count: u32;
   117→    }
   118→
   119→    // benchmark_soa_creation: SoA 생성 벤치마크
   120→    func benchmark_soa_creation(element_count: u32) -> PerformanceMetric {
   121→        let iterations = u64(100);  // 100번 반복
   122→        let timer = timer_start();
   123→
   124→        for i = 0; i < iterations; i = i + 1 {
   125→            let soa = Vector3DSoA {
   126→                x: make([f32], element_count),
   127→                y: make([f32], element_count),
   128→                z: make([f32], element_count),
   129→                count: element_count,
   130→            };
   131→
   132→            // 데이터 초기화
   133→            for j = 0; j < element_count; j = j + 1 {
   134→                soa.x[j] = f32(j) + 0.1;
   135→                soa.y[j] = f32(j) + 0.2;
   136→                soa.z[j] = f32(j) + 0.3;
   137→            }
   138→        }
   139→
   140→        let elapsed = timer.timer_stop();
   141→        let elapsed_micro = elapsed / NANO_PER_MICRO;
   142→        let throughput = f32(iterations * u64(element_count)) / (f32(elapsed_micro) / 1_000_000.0);
   143→        let latency = f32(elapsed_micro) / f32(iterations * u64(element_count));
   144→
   145→        return PerformanceMetric {
   146→            name: "SoA Creation",
   147→            iterations: iterations,
   148→            elapsed_time: elapsed_micro,
   149→            throughput: throughput,
   150→            latency: latency,
   151→            memory_used: u64(element_count) * 12,  // 3 * 4 bytes
   152→            cache_lines: (u64(element_count) * 4 + CACHE_LINE_SIZE - 1) / CACHE_LINE_SIZE,
   153→            is_soa: true,
   154→        };
   155→    }
   156→
   157→    // benchmark_soa_dot_product: SoA 점곱 벤치마크
   158→    func benchmark_soa_dot_product(element_count: u32) -> PerformanceMetric {
   159→        // 두 개의 SoA 벡터 생성
   160→        let v1 = Vector3DSoA {
   161→            x: make([f32], element_count),
   162→            y: make([f32], element_count),
   163→            z: make([f32], element_count),
   164→            count: element_count,
   165→        };
   166→
   167→        let v2 = Vector3DSoA {
   168→            x: make([f32], element_count),
   169→            y: make([f32], element_count),
   170→            z: make([f32], element_count),
   171→            count: element_count,
   172→        };
   173→
   174→        // 데이터 초기화
   175→        for j = 0; j < element_count; j = j + 1 {
   176→            v1.x[j] = 1.0;
   177→            v1.y[j] = 2.0;
   178→            v1.z[j] = 3.0;
   179→
   180→            v2.x[j] = 4.0;
   181→            v2.y[j] = 5.0;
   182→            v2.z[j] = 6.0;
   183→        }
   184→
   185→        let iterations = u64(1000);
   186→        let timer = timer_start();
   187→
   188→        for i = 0; i < iterations; i = i + 1 {
   189→            // 점곱 계산
   190→            for j = 0; j < element_count; j = j + 1 {
   191→                let dot = v1.x[j] * v2.x[j] +
   192→                          v1.y[j] * v2.y[j] +
   193→                          v1.z[j] * v2.z[j];
   194→            }
   195→        }
   196→
   197→        let elapsed = timer.timer_stop();
   198→        let elapsed_micro = elapsed / NANO_PER_MICRO;
   199→        let total_ops = iterations * u64(element_count);
   200→        let throughput = f32(total_ops) / (f32(elapsed_micro) / 1_000_000.0);
   201→        let latency = f32(elapsed_micro) / f32(total_ops);
   202→
   203→        return PerformanceMetric {
   204→            name: "SoA Dot Product",
   205→            iterations: iterations,
   206→            elapsed_time: elapsed_micro,
   207→            throughput: throughput,
   208→            latency: latency,
   209→            memory_used: u64(element_count) * 24,
   210→            cache_lines: (u64(element_count) * 8 + CACHE_LINE_SIZE - 1) / CACHE_LINE_SIZE,
   211→            is_soa: true,
   212→        };
   213→    }
   214→
   215→    // ========================================================================
   216→    // AoS 벤치마크 (기존 구현)
   217→    // ========================================================================
   218→
   219→    // 구조: Array of Structures
   220→    struct Vector3DAoS {
   221→        data: [Vector3D];
   222→        count: u32;
   223→    }
   224→
   225→    struct Vector3D {
   226→        x: f32;
   227→        y: f32;
   228→        z: f32;
   229→    }
   230→
   231→    // benchmark_aos_creation: AoS 생성 벤치마크
   232→    func benchmark_aos_creation(element_count: u32) -> PerformanceMetric {
   233→        let iterations = u64(100);
   234→        let timer = timer_start();
   235→
   236→        for i = 0; i < iterations; i = i + 1 {
   237→            let aos = Vector3DAoS {
   238→                data: make([Vector3D], element_count),
   239→                count: element_count,
   240→            };
   241→
   242→            // 데이터 초기화
   243→            for j = 0; j < element_count; j = j + 1 {
   244→                aos.data[j].x = f32(j) + 0.1;
   245→                aos.data[j].y = f32(j) + 0.2;
   246→                aos.data[j].z = f32(j) + 0.3;
   247→            }
   248→        }
   249→
   250→        let elapsed = timer.timer_stop();
   251→        let elapsed_micro = elapsed / NANO_PER_MICRO;
   252→        let throughput = f32(iterations * u64(element_count)) / (f32(elapsed_micro) / 1_000_000.0);
   253→        let latency = f32(elapsed_micro) / f32(iterations * u64(element_count));
   254→
   255→        return PerformanceMetric {
   256→            name: "AoS Creation",
   257→            iterations: iterations,
   258→            elapsed_time: elapsed_micro,
   259→            throughput: throughput,
   260→            latency: latency,
   261→            memory_used: u64(element_count) * 12,
   262→            cache_lines: (u64(element_count) * 12 + CACHE_LINE_SIZE - 1) / CACHE_LINE_SIZE,
   263→            is_soa: false,
   264→        };
   265→    }
   266→
   267→    // benchmark_aos_dot_product: AoS 점곱 벤치마크
   268→    func benchmark_aos_dot_product(element_count: u32) -> PerformanceMetric {
   269→        // 두 개의 AoS 벡터 생성
   270→        let v1 = Vector3DAoS {
   271→            data: make([Vector3D], element_count),
   272→            count: element_count,
   273→        };
   274→
   275→        let v2 = Vector3DAoS {
   276→            data: make([Vector3D], element_count),
   277→            count: element_count,
   278→        };
   279→
   280→        // 데이터 초기화
   281→        for j = 0; j < element_count; j = j + 1 {
   282→            v1.data[j].x = 1.0;
   283→            v1.data[j].y = 2.0;
   284→            v1.data[j].z = 3.0;
   285→
   286→            v2.data[j].x = 4.0;
   287→            v2.data[j].y = 5.0;
   288→            v2.data[j].z = 6.0;
   289→        }
   290→
   291→        let iterations = u64(1000);
   292→        let timer = timer_start();
   293→
   294→        for i = 0; i < iterations; i = i + 1 {
   295→            // 점곱 계산
   296→            for j = 0; j < element_count; j = j + 1 {
   297→                let dot = v1.data[j].x * v2.data[j].x +
   298→                          v1.data[j].y * v2.data[j].y +
   299→                          v1.data[j].z * v2.data[j].z;
   300→            }
   301→        }
   302→
   303→        let elapsed = timer.timer_stop();
   304→        let elapsed_micro = elapsed / NANO_PER_MICRO;
   305→        let total_ops = iterations * u64(element_count);
   306→        let throughput = f32(total_ops) / (f32(elapsed_micro) / 1_000_000.0);
   307→        let latency = f32(elapsed_micro) / f32(total_ops);
   308→
   309→        return PerformanceMetric {
   310→            name: "AoS Dot Product",
   311→            iterations: iterations,
   312→            elapsed_time: elapsed_micro,
   313→            throughput: throughput,
   314→            latency: latency,
   315→            memory_used: u64(element_count) * 24,
   316→            cache_lines: (u64(element_count) * 12 + CACHE_LINE_SIZE - 1) / CACHE_LINE_SIZE,
   317→            is_soa: false,
   318→        };
   319→    }
   320→
   321→    // ========================================================================
   322→    // 벤치마크 분석
   323→    // ========================================================================
   324→
   325→    // calc_improvement: SoA vs AoS 성능 개선율 계산
   326→    func calc_improvement(soa_metric: PerformanceMetric, aos_metric: PerformanceMetric) -> f32 {
   327→        if aos_metric.throughput == 0.0 {
   328→            return 0.0;
   329→        }
   330→        return (soa_metric.throughput - aos_metric.throughput) / aos_metric.throughput * 100.0;
   331→    }
