   333→    // ========================================================================
   334→    // 리포트 생성
   335→    // ========================================================================
   336→
   337→    // report_metric: 단일 메트릭 출력
   338→    func report_metric(metric: PerformanceMetric) {
   339→        let layout = if metric.is_soa { "SoA" } else { "AoS" };
   340→
   341→        print("📊 " + metric.name + " (" + layout + ")");
   342→        print("   Iterations:   " + metric.iterations);
   343→        print("   Total Time:   " + metric.elapsed_time + " μs");
   344→        print("   Throughput:   " + metric.throughput + " ops/sec");
   345→        print("   Latency:      " + metric.latency + " μs/op");
   346→        print("   Memory Used:  " + metric.memory_used + " bytes");
   347→        print("   Cache Lines:  " + metric.cache_lines);
   348→        print("");
   349→    }
   350→
   351→    // report_comparison: SoA vs AoS 비교 리포트
   352→    func report_comparison(soa: PerformanceMetric, aos: PerformanceMetric) {
   353→        let improvement = calc_improvement(soa, aos);
   354→        let latency_improvement = (aos.latency - soa.latency) / aos.latency * 100.0;
   355→
   356→        print("╔════════════════════════════════════════════╗");
   357→        print("║ Performance Comparison: SoA vs AoS        ║");
   358→        print("╚════════════════════════════════════════════╝");
   359→        print("");
   360→
   361→        print("Throughput:");
   362→        print("  AoS: " + aos.throughput + " ops/sec");
   363→        print("  SoA: " + soa.throughput + " ops/sec");
   364→        print("  Improvement: " + improvement + "%");
   365→        print("");
   366→
   367→        print("Latency:");
   368→        print("  AoS: " + aos.latency + " μs/op");
   369→        print("  SoA: " + soa.latency + " μs/op");
   370→        print("  Improvement: " + latency_improvement + "%");
   371→        print("");
   372→
   373→        print("Cache Efficiency:");
   374→        print("  AoS: " + aos.cache_lines + " cache lines");
   375→        print("  SoA: " + soa.cache_lines + " cache lines");
   376→        let cache_reduction = f32(aos.cache_lines - soa.cache_lines) / f32(aos.cache_lines) * 100.0;
   377→        print("  Reduction: " + cache_reduction + "%");
   378→        print("");
   379→    }
   380→}
