## 모듈 2: `stdlib/collections.fl` (350-400줄)

### 핵심 설계 원칙

FreeLang에 제네릭이 없으므로 **`i64` 슬라이스를 기본 컨테이너로 채택**합니다. 이는 Zero-Copy-DB의 실제 사용 패턴(정수 ID, 오프셋, 카운터)과 일치합니다. 부동소수점 컬렉션은 `[f32]` 전용 함수 세트를 별도 제공합니다.

이 설계는 기존 코드베이스의 `make([f32], n)`, `va.x_data[i]` 패턴과 일관성을 유지합니다.

### 핵심 구조체

```fl
module collections {
    // 정렬 방향 상수
    const SORT_ASC:  i32 = 1;
    const SORT_DESC: i32 = -1;

    // 반복자 상태 (슬라이스 + 커서)
    struct Iter {
        data:   [i64];
        pos:    i32;
        length: i32;
    }

    // 슬라이스 슬라이스 (zip용)
    struct ZipPair {
        left:  i64;
        right: i64;
    }
}
```

### 주요 함수 시그니처 및 의사코드

**이터레이터 생성/소비**
```
func iter(data: [i64]) -> Iter
    return Iter{ data: data, pos: 0, length: len(data) }

func (it: *Iter) has_next() -> bool
    return it.pos < it.length

func (it: *Iter) next() -> (i64, bool)
    if !it.has_next() → return (0, false)
    let val = it.data[it.pos]; it.pos++ ; return (val, true)
```

**변환 함수 (슬라이스 → 슬라이스)**
```
func map_fn(data: [i64], factor: i64) -> [i64]
    // FreeLang에 1급 함수 없음 → factor 곱셈 변환으로 구체화
    result = make([i64], len(data))
    for i in data: result[i] = data[i] * factor
    return result

func filter_gt(data: [i64], threshold: i64) -> [i64]
    // threshold 초과 값만 수집
    result = make([i64], 0)
    for each val: if val > threshold → result.push(val)
    return result

func filter_range(data: [i64], min: i64, max: i64) -> [i64]
    // [min, max] 범위 값만 수집

func map_add(data: [i64], offset: i64) -> [i64]
    // 각 원소에 offset 더하기
```

**집계 함수 (슬라이스 → 단일 값)**
```
func reduce(data: [i64], initial: i64) -> i64
    // 누적 합계 (reduce-sum 의미)
    acc = initial
    for each val: acc = acc + val
    return acc

func sum(data: [i64]) -> i64
    // reduce(data, 0)의 단축형

func min(data: [i64]) -> (i64, bool)
    // 빈 슬라이스 → (0, false)
    let min_val = data[0]
    for each val: if val < min_val → min_val = val
    return (min_val, true)

func max(data: [i64]) -> (i64, bool)

func count(data: [i64]) -> i32
    return len(data)

func count_where(data: [i64], threshold: i64) -> i32
    // threshold 이상인 원소 개수
```

**검색 함수**
```
func find(data: [i64], target: i64) -> (i32, bool)
    // 선형 탐색, 첫 번째 일치 인덱스 반환
    for i: if data[i] == target → return (i, true)
    return (-1, false)

func find_all(data: [i64], target: i64) -> [i32]
    // 일치하는 모든 인덱스 수집

func contains(data: [i64], target: i64) -> bool
    // find의 bool 버전
```

**슬라이스 조작**
```
func take(data: [i64], n: i32) -> [i64]
    // 앞의 n개 반환
    if n >= len(data) → return data
    result = make([i64], n)
    for i < n: result[i] = data[i]
    return result

func skip(data: [i64], n: i32) -> [i64]
    // 앞의 n개 제외하고 반환
    result = make([i64], 0)
    for i = n; i < len(data): result.push(data[i])
    return result

func zip(a: [i64], b: [i64]) -> [ZipPair]
    // 짧은 쪽 기준으로 ZipPair 배열 생성

func foreach(data: [i64], label: string)
    // label을 prefix로 각 원소 print 출력 (부수효과 목적)
```

**정렬**
```
func sort_asc(data: [i64]) -> [i64]
    // 삽입 정렬 (소규모 데이터), 원본 불변 → 새 슬라이스 반환
    result = data 복사
    insertion sort 루프
    return result

