module collections {
    // === 상수 ===
    const SORT_ASC:  i32 = 1;
    const SORT_DESC: i32 = -1;

    // === 데이터 구조체 ===
    // 슬라이스 반복자
    struct Iter {
        data:   [i64];
        pos:    i32;
        length: i32;
    }

    // zip 결과용 쌍 구조체
    struct ZipPair {
        left:  i64;
        right: i64;
    }

    // === 이터레이터 함수 ===

    // 슬라이스로부터 이터레이터 생성
    func iter(data: [i64]) -> Iter {
        return Iter{
            data:   data,
            pos:    0,
            length: len(data),
        };
    }

    // 이터레이터가 다음 원소를 가지고 있는지 확인
    @inline
    func (it: *Iter) has_next() -> bool {
        return it.pos < it.length;
    }

    // 이터레이터에서 다음 원소 추출
    @inline
    func (it: *Iter) next() -> (i64, bool) {
        if !it.has_next() {
            return (0, false);
        }
        let val = it.data[it.pos];
        it.pos = it.pos + 1;
        return (val, true);
    }

    // === 집계 함수 ===

    // 슬라이스의 모든 원소 합계
    func sum(data: [i64]) -> i64 {
        let acc = i64(0);
        let i = 0;
        for i = 0; i < len(data); i = i + 1 {
            acc = acc + data[i];
        }
        return acc;
    }

    // 슬라이스의 최솟값 (오버플로우 방지: i64 사용)
    func min(data: [i64]) -> (i64, bool) {
        if len(data) == 0 {
            return (0, false);
        }
        let min_val = data[0];
        let i = 1;
        for i = 1; i < len(data); i = i + 1 {
            let v = data[i];
            if v < min_val {
                min_val = v;
            }
        }
        return (min_val, true);
    }

    // 슬라이스의 최댓값
    func max(data: [i64]) -> (i64, bool) {
        if len(data) == 0 {
            return (0, false);
        }
        let max_val = data[0];
        let i = 1;
        for i = 1; i < len(data); i = i + 1 {
            let v = data[i];
            if v > max_val {
                max_val = v;
            }
        }
        return (max_val, true);
    }

    // 슬라이스의 원소 개수
    @inline
    func count(data: [i64]) -> i32 {
        return len(data);
    }

    // threshold 이상인 원소 개수
    func count_where(data: [i64], threshold: i64) -> i32 {
        let cnt = 0;
        let i = 0;
        for i = 0; i < len(data); i = i + 1 {
            if data[i] >= threshold {
                cnt = cnt + 1;
            }
        }
        return cnt;
    }

    // 누적 합계 (initial값에서 시작)
    func reduce(data: [i64], initial: i64) -> i64 {
        let acc = initial;
        let i = 0;
        for i = 0; i < len(data); i = i + 1 {
            acc = acc + data[i];
        }
        return acc;
    }

    // === 검색 함수 ===

    // target과 일치하는 첫 번째 인덱스 반환
    func find(data: [i64], target: i64) -> (i32, bool) {
        let i = 0;
        for i = 0; i < len(data); i = i + 1 {
            if data[i] == target {
                return (i32(i), true);
            }
        }
        return (-1, false);
    }

    // target과 일치하는 모든 인덱스 수집
    func find_all(data: [i64], target: i64) -> [i32] {
        let indices = make([i32], 0);
        let i = 0;
        for i = 0; i < len(data); i = i + 1 {
            if data[i] == target {
                indices.push(i32(i));
            }
        }
        return indices;
    }

    // target이 슬라이스에 포함되어 있는지 확인
    func contains(data: [i64], target: i64) -> bool {
