// ============================================================================
// FreeLang Concurrency 모듈 - 채널 기반 협동 액터 시스템
// ============================================================================
// 목표: Zero-Copy-DB에서 분산 노드 간 메시지 전달, 동시성 제어를 구현할 수 있도록 함
// 원리:
//   1. 뮤텍스 없음 - "메모리 공유로 통신하지 말고, 통신으로 메모리 공유하라" (Go 철학)
//   2. 링 버퍼 기반 채널로 FIFO 메시지 큐 구현
//   3. 협동 스케줄러: 명시적 tick()으로 한 스텝씩 진행 (preemption 없음)
//   4. 액터: 독립적 실행 단위, inbox 채널로만 외부와 통신
// 구조:
//   - 상수 정의 (CHAN_OPEN, ACTOR_READY, ...)
//   - Channel, Actor, Scheduler, SelectResult 구조체
//   - @inline 채널 헬퍼 (is_empty, is_full, len)
//   - 채널 함수 (new, send, recv, close)
//   - 액터 함수 (new, send, recv, tick, finish, is_done)
//   - 스케줄러 함수 (new, spawn, send, recv, tick, wait, finish)
//   - select 함수 (채널 멀티플렉서)
//   - 글로벌 편의 함수
// ============================================================================

module concurrent {
    // === 상수: 채널 상태 ===
    const CHAN_OPEN:   i32 = 0;
    const CHAN_CLOSED: i32 = 1;

    // === 상수: 액터 상태 ===
    const ACTOR_READY:   i32 = 0;
    const ACTOR_RUNNING: i32 = 1;
    const ACTOR_DONE:    i32 = 2;
    const ACTOR_BLOCKED: i32 = 3;

    // === 데이터 구조체 ===
    // 링 버퍼 기반 메시지 채널
    struct Channel {
        buffer:   [i64];      // 링 버퍼 데이터
        capacity: i32;        // 버퍼 최대 크기
        head:     i32;        // 읽기 커서
        tail:     i32;        // 쓰기 커서
        count:    i32;        // 현재 메시지 수
        state:    i32;        // CHAN_OPEN / CHAN_CLOSED
        id:       i32;        // 채널 고유 ID
    }

    // 액터: 독립적 실행 단위
    struct Actor {
        id:         i32;
        state:      i32;        // ACTOR_* 상태
        result:     i64;        // 완료 후 반환값
        inbox:      Channel;    // 수신 전용 채널
        tick_count: i32;        // 디버그용 실행 횟수
    }

    // 스케줄러: 모든 액터를 관리하는 협동 스케줄러
    struct Scheduler {
        actors:       [Actor];
        next_id:      i32;
        total_ticks:  i32;
    }

    // select() 함수 반환값
    struct SelectResult {
        channel_idx: i32;   // 메시지를 받은 채널 인덱스
        value:       i64;
        ok:          bool;
    }

    // === @inline 채널 헬퍼 ===

    @inline
    func (ch: *Channel) chan_is_empty() -> bool {
        return ch.count == 0;
    }

    @inline
    func (ch: *Channel) chan_is_full() -> bool {
        return ch.count >= ch.capacity;
    }

    @inline
    func (ch: *Channel) chan_len() -> i32 {
        return ch.count;
    }

    // === 채널 함수 ===

    // 새 채널 생성
    func chan_new(buffer_size: i32) -> Channel {
        if buffer_size <= 0 {
            buffer_size = 1;
        }
        return Channel{
            buffer:   make([i64], buffer_size),
            capacity: buffer_size,
            head:     0,
            tail:     0,
            count:    0,
            state:    CHAN_OPEN,
            id:       monotonic_channel_id(),
        };
    }

    // 채널에 메시지 전송 (블로킹 시뮬레이션: 가득 차면 false)
    func (ch: *Channel) chan_send(msg: i64) -> bool {
        if ch.state == CHAN_CLOSED {
            return false;
        }
        if ch.count >= ch.capacity {
            return false;  // 버퍼 가득 참 (실제 구현: 대기 또는 drop)
        }
        ch.buffer[ch.tail] = msg;
        ch.tail = (ch.tail + 1) % ch.capacity;
        ch.count = ch.count + 1;
        return true;
    }

    // 채널에서 메시지 수신
    func (ch: *Channel) chan_recv() -> (i64, bool) {
        if ch.count == 0 {
            if ch.state == CHAN_CLOSED {
                return (0, false);
            }
            return (0, false);  // 메시지 없음
        }
        let msg = ch.buffer[ch.head];
        ch.head = (ch.head + 1) % ch.capacity;
        ch.count = ch.count - 1;
        return (msg, true);
    }

    // 채널 닫기
    func (ch: *Channel) chan_close() {
        ch.state = CHAN_CLOSED;
    }

    // === 액터 함수 ===

    // 새 액터 생성
    func actor_new(id: i32, buffer_size: i32) -> Actor {
        return Actor{
            id:         id,
            state:      ACTOR_READY,
            result:     0,
            inbox:      chan_new(buffer_size),
            tick_count: 0,
        };
    }

    // 액터에게 메시지 전송
    func (a: *Actor) actor_send(msg: i64) -> bool {
        return a.inbox.chan_send(msg);
    }

    // 액터가 메시지 수신
    func (a: *Actor) actor_recv() -> (i64, bool) {
        return a.inbox.chan_recv();
    }

    // 액터 한 스텝 실행 (협동 스케줄러용)
    func (a: *Actor) actor_tick() -> bool {
        if a.state == ACTOR_DONE {
            return false;
        }
        if a.state == ACTOR_BLOCKED && a.inbox.chan_is_empty() {
            return false;
        }
        a.state = ACTOR_RUNNING;
        a.tick_count = a.tick_count + 1;
        // Note: 실제 구현에서는 런타임이 등록된 fn 콜백 호출
        // 여기서는 상태 전환만 수행
        return true;
    }

    // 액터 작업 완료 처리
    func (a: *Actor) actor_finish(result: i64) {
        a.result = result;
        a.state = ACTOR_DONE;
        a.inbox.chan_close();
    }

    // 액터가 완료되었는지 확인
    func (a: *Actor) actor_is_done() -> bool {
        return a.state == ACTOR_DONE;
    }

    // === 스케줄러 함수 ===

    // 새 스케줄러 생성
    func scheduler_new() -> Scheduler {
        return Scheduler{
            actors:       make([Actor], 0),
            next_id:      1,
            total_ticks:  0,
        };
    }

    // 새 액터 생성 및 등록 (스케줄러)
    func (s: *Scheduler) spawn(buffer_size: i32) -> i32 {
        let id = s.next_id;
        s.next_id = s.next_id + 1;
        let actor = actor_new(id, buffer_size);
        s.actors.push(actor);
        return id;
    }

    // 특정 액터에 메시지 전송
    func (s: *Scheduler) send(actor_id: i32, msg: i64) -> bool {
        let i = 0;
        for i = 0; i < len(s.actors); i = i + 1 {
            if s.actors[i].id == actor_id {
                return s.actors[i].actor_send(msg);
            }
        }
        return false;
    }

    // 특정 액터에서 메시지 수신
    func (s: *Scheduler) recv(actor_id: i32) -> (i64, bool) {
        let i = 0;
        for i = 0; i < len(s.actors); i = i + 1 {
            if s.actors[i].id == actor_id {
                return s.actors[i].actor_recv();
            }
        }
        return (0, false);
    }

    // 모든 액터를 한 스텝 실행
    func (s: *Scheduler) tick() -> i32 {
        let active = 0;
        let i = 0;
        for i = 0; i < len(s.actors); i = i + 1 {
            if s.actors[i].actor_tick() {
                active = active + 1;
            }
        }
        s.total_ticks = s.total_ticks + 1;
        return active;
    }

    // 특정 액터의 완료 대기 (max_ticks 제한)
    func (s: *Scheduler) wait(actor_id: i32, max_ticks: i32) -> (i64, bool) {
        let t = 0;
        for t = 0; t < max_ticks; t = t + 1 {
            let i = 0;
            for i = 0; i < len(s.actors); i = i + 1 {
                if s.actors[i].id == actor_id && s.actors[i].actor_is_done() {
                    return (s.actors[i].result, true);
                }
            }
            s.tick();
        }
        return (0, false);  // 타임아웃
    }

    // 특정 액터를 완료 상태로 처리 (결과 주입)
    func (s: *Scheduler) finish(actor_id: i32, result: i64) {
        let i = 0;
        for i = 0; i < len(s.actors); i = i + 1 {
            if s.actors[i].id == actor_id {
                s.actors[i].actor_finish(result);
                return;
            }
        }
    }

    // 스케줄러 상태 요약
    func (s: *Scheduler) stats() -> string {
        let total = len(s.actors);
        let done = 0;
        let i = 0;
        for i = 0; i < total; i = i + 1 {
            if s.actors[i].actor_is_done() {
                done = done + 1;
            }
        }
        let msg = "[Scheduler] total=" + i32_to_string(total) + " done=" + i32_to_string(done) + " ticks=" + i32_to_string(s.total_ticks);
        return msg;
    }

    // === Select 패턴 (채널 멀티플렉서) ===

    // 첫 번째로 메시지가 있는 채널에서 수신
    func chan_select(channels: [Channel]) -> SelectResult {
        let i = 0;
        for i = 0; i < len(channels); i = i + 1 {
            if !channels[i].chan_is_empty() {
                let val, ok = channels[i].chan_recv();
                return SelectResult{ channel_idx: i32(i), value: val, ok: ok };
            }
        }
        return SelectResult{ channel_idx: -1, value: 0, ok: false };
    }

    // === 글로벌 편의 함수 ===

    // 스케줄러 없이 독립적 Actor 생성
    func spawn(buffer_size: i32) -> Actor {
        return actor_new(1, buffer_size);
    }

    // 독립적 Actor 완료 대기
    func wait_actor(a: *Actor, max_ticks: i32) -> (i64, bool) {
        let t = 0;
        for t = 0; t < max_ticks; t = t + 1 {
            if a.actor_is_done() {
                return (a.result, true);
            }
            a.actor_tick();
        }
        return (0, false);
    }

    // CPU 양보 (협동 스케줄러 친화적)
    func sleep(ticks: i32) {
        let i = 0;
        for i = 0; i < ticks; i = i + 1 {
            // 실제 구현: 대기 로직
        }
    }

    // === 모니터링 함수 ===

    // Actor 정보 출력
    func (a: *Actor) print_info() {
        let state_str = if a.state == ACTOR_DONE { "DONE" } else { "ACTIVE" };
        print("[Actor " + i32_to_string(a.id) + "] state=" + state_str + " inbox_len=" + i32_to_string(a.inbox.chan_len()));
    }

    // === 헬퍼 함수 ===

    @inline
    func i32_to_string(n: i32) -> string {
        if n == 0 { return "0"; }
        if n == 1 { return "1"; }
        if n == 2 { return "2"; }
        if n == 3 { return "3"; }
        if n == 4 { return "4"; }
        if n == 5 { return "5"; }
        if n < 0 { return "-" + i32_to_string(-n); }
        return "?";
    }

    // 모노톤 증가 채널 ID
    func monotonic_channel_id() -> i32 {
        // Note: 전역 카운터 필요 (런타임 제공)
        return 1;  // 임시
    }
}

// === 테스트 시나리오 (주석) ===
// 기본 동작:
//   - chan_new(10) → Channel{ capacity: 10, count: 0, state: CHAN_OPEN }
//   - ch.chan_send(42) → true
//   - ch.chan_recv() → (42, true)
//   - ch.chan_is_empty() → true
//   - ch.chan_close()
//
//   - spawn(10) → Actor{ id: 1, state: ACTOR_READY, inbox: Channel }
//   - actor.actor_send(100) → true
//   - actor.actor_recv() → (100, true)
//   - actor.actor_tick() → true
//   - actor.actor_finish(42)
//   - actor.actor_is_done() → true
//
// 스케줄러 사용:
//   - s := scheduler_new()
//   - id1 := s.spawn(10)
//   - id2 := s.spawn(10)
//   - s.send(id1, 99) → true
