    21→
    22→module collections {
    23→    // === 상수 ===
    24→    const SORT_ASC:  i32 = 1;
    25→    const SORT_DESC: i32 = -1;
    26→
    27→    // === 데이터 구조체 ===
    28→    // 슬라이스 반복자
    29→    struct Iter {
    30→        data:   [i64];
    31→        pos:    i32;
    32→        length: i32;
    33→    }
    34→
    35→    // zip 결과용 쌍 구조체
    36→    struct ZipPair {
    37→        left:  i64;
    38→        right: i64;
    39→    }
    40→
    41→    // === 이터레이터 함수 ===
    42→
    43→    // 슬라이스로부터 이터레이터 생성
    44→    func iter(data: [i64]) -> Iter {
    45→        return Iter{
    46→            data:   data,
    47→            pos:    0,
    48→            length: len(data),
    49→        };
    50→    }
    51→
    52→    // 이터레이터가 다음 원소를 가지고 있는지 확인
    53→    @inline
    54→    func (it: *Iter) has_next() -> bool {
    55→        return it.pos < it.length;
    56→    }
    57→
    58→    // 이터레이터에서 다음 원소 추출
    59→    @inline
    60→    func (it: *Iter) next() -> (i64, bool) {
    61→        if !it.has_next() {
    62→            return (0, false);
    63→        }
    64→        let val = it.data[it.pos];
    65→        it.pos = it.pos + 1;
    66→        return (val, true);
    67→    }
    68→
    69→    // === 집계 함수 ===
    70→
    71→    // 슬라이스의 모든 원소 합계
    72→    func sum(data: [i64]) -> i64 {
    73→        let acc = i64(0);
    74→        let i = 0;
    75→        for i = 0; i < len(data); i = i + 1 {
    76→            acc = acc + data[i];
    77→        }
    78→        return acc;
    79→    }
    80→
    81→    // 슬라이스의 최솟값 (오버플로우 방지: i64 사용)
    82→    func min(data: [i64]) -> (i64, bool) {
    83→        if len(data) == 0 {
    84→            return (0, false);
    85→        }
    86→        let min_val = data[0];
    87→        let i = 1;
    88→        for i = 1; i < len(data); i = i + 1 {
    89→            let v = data[i];
    90→            if v < min_val {
    91→                min_val = v;
    92→            }
    93→        }
    94→        return (min_val, true);
    95→    }
    96→
    97→    // 슬라이스의 최댓값
    98→    func max(data: [i64]) -> (i64, bool) {
    99→        if len(data) == 0 {
   100→            return (0, false);
   101→        }
   102→        let max_val = data[0];
   103→        let i = 1;
   104→        for i = 1; i < len(data); i = i + 1 {
   105→            let v = data[i];
   106→            if v > max_val {
   107→                max_val = v;
   108→            }
   109→        }
   110→        return (max_val, true);
   111→    }
   112→
   113→    // 슬라이스의 원소 개수
   114→    @inline
   115→    func count(data: [i64]) -> i32 {
   116→        return len(data);
   117→    }
   118→
   119→    // threshold 이상인 원소 개수
   120→    func count_where(data: [i64], threshold: i64) -> i32 {
   121→        let cnt = 0;
   122→        let i = 0;
   123→        for i = 0; i < len(data); i = i + 1 {
   124→            if data[i] >= threshold {
   125→                cnt = cnt + 1;
   126→            }
   127→        }
   128→        return cnt;
   129→    }
