   434→    // === 헬퍼 함수 ===
   435→
   436→    @inline
   437→    func i64_to_string(n: i64) -> string {
   438→        if n == 0 { return "0"; }
   439→        if n == 1 { return "1"; }
   440→        if n == 2 { return "2"; }
   441→        if n < 0 { return "-" + i64_to_string(-n); }
   442→        return "?";
   443→    }
   444→
   445→    // 배열을 구분자로 연결
   446→    func join(parts: [string], sep: string) -> string {
   447→        if len(parts) == 0 {
   448→            return "";
   449→        }
   450→        let result = parts[0];
   451→        let i = 1;
   452→        for i = 1; i < len(parts); i = i + 1 {
   453→            result = result + sep + parts[i];
   454→        }
   455→        return result;
   456→    }
   457→}
