    49→    // 메모리 정렬 정보
    50→    struct AlignmentInfo {
    51→        x_addr: u64;
    52→        y_addr: u64;
    53→        z_addr: u64;
    54→        x_aligned: bool;
    55→        y_aligned: bool;
    56→        z_aligned: bool;
    57→        is_aligned: bool;
    58→    }
    59→
    60→    // 성능 통계
    61→    struct VectorStats {
    62→        count: u32;
    63→        capacity: u32;
    64→        memory_bytes: u64;
    65→        cache_lines: u32;
    66→        simd_ops_per_cycle: u32;
