// ============================================================================
// FreeLang JSON 모듈 - JSON 파싱 및 직렬화
// ============================================================================
// 목표: Zero-Copy-DB에서 설정, API 응답, 벤치마크 결과 등을 JSON으로 처리할 수 있도록 함
// 원리:
//   1. JSON 값을 태그드 유니온 구조체로 표현 (null, bool, int, float, string, array, object)
//   2. 재귀 하강 파서(Recursive Descent Parser) 패턴 사용
//   3. 파서 상태(커서 위치) 추적으로 에러 위치 파악 가능
//   4. stringify로 다시 JSON 문자열 생성 가능
// 구조:
//   - 상수 정의 (KIND_*)
//   - JsonValue, Parser 구조체
//   - @inline 팩토리 함수 (make_*)
//   - Parser 헬퍼 메서드 (@inline: peek, advance, skip_ws)
//   - parse_* 파서 함수들 (재귀적)
//   - 공개 API (parse, stringify, get, merge, pretty)
// ============================================================================

module json {
    // === 상수: JSON 값 종류 ===
    const KIND_NULL:   i32 = 0;
    const KIND_BOOL:   i32 = 1;
    const KIND_INT:    i32 = 2;
    const KIND_FLOAT:  i32 = 3;
    const KIND_STRING: i32 = 4;
    const KIND_ARRAY:  i32 = 5;
    const KIND_OBJECT: i32 = 6;

    // === 데이터 구조체 ===
    // JSON 값 (태그드 유니온)
    struct JsonValue {
        kind:        i32;              // KIND_* 상수
        bool_val:    bool;             // KIND_BOOL용
        int_val:     i64;              // KIND_INT용
        float_val:   f64;              // KIND_FLOAT용
        str_val:     string;           // KIND_STRING용
        array_vals:  [JsonValue];      // KIND_ARRAY용
        object_keys: [string];         // KIND_OBJECT용 키
        object_vals: [JsonValue];      // KIND_OBJECT용 값
    }

    // JSON 파서 상태
    struct Parser {
        input: string;
        pos:   i32;
        len:   i32;
    }

    // === @inline 팩토리 함수 ===

    @inline
    func make_null() -> JsonValue {
        return JsonValue{
            kind: KIND_NULL, bool_val: false, int_val: 0,
            float_val: 0.0, str_val: "", array_vals: make([JsonValue], 0),
            object_keys: make([string], 0), object_vals: make([JsonValue], 0),
        };
    }

    @inline
    func make_bool(b: bool) -> JsonValue {
        return JsonValue{
            kind: KIND_BOOL, bool_val: b, int_val: 0,
            float_val: 0.0, str_val: "", array_vals: make([JsonValue], 0),
            object_keys: make([string], 0), object_vals: make([JsonValue], 0),
        };
    }

    @inline
    func make_int(n: i64) -> JsonValue {
        return JsonValue{
            kind: KIND_INT, bool_val: false, int_val: n,
            float_val: 0.0, str_val: "", array_vals: make([JsonValue], 0),
            object_keys: make([string], 0), object_vals: make([JsonValue], 0),
        };
    }

    @inline
    func make_float(f: f64) -> JsonValue {
        return JsonValue{
            kind: KIND_FLOAT, bool_val: false, int_val: 0,
            float_val: f, str_val: "", array_vals: make([JsonValue], 0),
            object_keys: make([string], 0), object_vals: make([JsonValue], 0),
        };
    }

    @inline
    func make_string(s: string) -> JsonValue {
        return JsonValue{
            kind: KIND_STRING, bool_val: false, int_val: 0,
            float_val: 0.0, str_val: s, array_vals: make([JsonValue], 0),
            object_keys: make([string], 0), object_vals: make([JsonValue], 0),
        };
    }

    // === Parser 헬퍼 메서드 ===

    // 현재 위치의 문자 코드 반환 (범위 초과 시 -1)
    @inline
    func (p: *Parser) peek() -> i32 {
        if p.pos >= p.len {
            return -1;
        }
        // 런타임이 제공하는 char_at 함수 호출
        return char_at(p.input, p.pos);
    }

    // 파서 커서 1칸 진진
    @inline
    func (p: *Parser) advance() {
        if p.pos < p.len {
            p.pos = p.pos + 1;
        }
    }

    // 공백(space, tab, CR, LF) 스킵
    func (p: *Parser) skip_ws() {
        let c = 0;
        for c = 1; c > 0; {
            c = p.peek();
            if c == 32 || c == 9 || c == 10 || c == 13 {  // space, tab, LF, CR
                p.advance();
            } else {
                c = 0;  // break
            }
        }
    }

    // === 파서 함수 ===

    // 문자열 파싱 (큰따옴표 내 내용)
    func (p: *Parser) parse_string() -> (string, bool) {
        let c = p.peek();
        if c != 34 {  // '"'
            return ("", false);
        }
        p.advance();  // 시작 '"' 스킵

        let result = "";
        for c = 1; c > 0; {
            c = p.peek();
            if c == -1 {
                return ("", false);  // EOF
            }
            if c == 34 {  // '"'
                p.advance();
                return (result, true);
            }
            // 문자 코드를 문자로 변환 후 추가
            let ch = char_from_code(c);
            result = result + ch;
            p.advance();
        }
        return (result, false);
    }

    // 숫자 파싱 (정수 또는 부동소수점)
    func (p: *Parser) parse_number() -> (JsonValue, bool) {
        // Note: 숫자 문자열 추출 후 정수/부동 판정 필요
        // 여기서는 간단히 정수 반환
        let n = i64(0);
        return (make_int(n), true);
    }

    // 배열 파싱 [ ... ]
    func (p: *Parser) parse_array() -> (JsonValue, bool) {
        let c = p.peek();
        if c != 91 {  // '['
            return (make_null(), false);
        }
        p.advance();

        let vals = make([JsonValue], 0);
        p.skip_ws();

        // 빈 배열 확인
        c = p.peek();
        if c == 93 {  // ']'
            p.advance();
            return (JsonValue{
                kind: KIND_ARRAY, bool_val: false, int_val: 0, float_val: 0.0, str_val: "",
                array_vals: vals, object_keys: make([string], 0), object_vals: make([JsonValue], 0),
            }, true);
        }

        // 배열 요소 파싱
        for c = 1; c > 0; {
            let val, ok = p.parse_value();
            if !ok {
                return (make_null(), false);
            }
            vals.push(val);

            p.skip_ws();
            c = p.peek();
            if c == 93 {  // ']'
                p.advance();
                return (JsonValue{
                    kind: KIND_ARRAY, bool_val: false, int_val: 0, float_val: 0.0, str_val: "",
                    array_vals: vals, object_keys: make([string], 0), object_vals: make([JsonValue], 0),
                }, true);
            }
            if c == 44 {  // ','
                p.advance();
                p.skip_ws();
            } else {
                return (make_null(), false);
            }
        }
        return (make_null(), false);
    }

    // 객체 파싱 { ... }
    func (p: *Parser) parse_object() -> (JsonValue, bool) {
        let c = p.peek();
        if c != 123 {  // '{'
            return (make_null(), false);
        }
        p.advance();

        let keys = make([string], 0);
        let vals = make([JsonValue], 0);
        p.skip_ws();

        // 빈 객체 확인
        c = p.peek();
        if c == 125 {  // '}'
            p.advance();
            return (JsonValue{
                kind: KIND_OBJECT, bool_val: false, int_val: 0, float_val: 0.0, str_val: "",
                array_vals: make([JsonValue], 0), object_keys: keys, object_vals: vals,
            }, true);
        }

        // 키-값 쌍 파싱
        for c = 1; c > 0; {
            // 키는 반드시 문자열
            let key, ok = p.parse_string();
            if !ok {
                return (make_null(), false);
            }
            p.skip_ws();

            // ':'
            c = p.peek();
            if c != 58 {  // ':'
                return (make_null(), false);
            }
            p.advance();
            p.skip_ws();

            // 값
            let val, ok2 = p.parse_value();
            if !ok2 {
                return (make_null(), false);
            }
            keys.push(key);
            vals.push(val);

            p.skip_ws();
            c = p.peek();
            if c == 125 {  // '}'
                p.advance();
                return (JsonValue{
                    kind: KIND_OBJECT, bool_val: false, int_val: 0, float_val: 0.0, str_val: "",
                    array_vals: make([JsonValue], 0), object_keys: keys, object_vals: vals,
                }, true);
            }
            if c == 44 {  // ','
                p.advance();
                p.skip_ws();
            } else {
                return (make_null(), false);
            }
        }
        return (make_null(), false);
    }

    // 값 파싱 (진입점)
    func (p: *Parser) parse_value() -> (JsonValue, bool) {
        p.skip_ws();
        let c = p.peek();

        if c == 110 {  // 'n' in "null"
            p.advance();  // 간단히: null 스킵
            return (make_null(), true);
        }
        if c == 116 {  // 't' in "true"
            p.advance();
            return (make_bool(true), true);
        }
        if c == 102 {  // 'f' in "false"
            p.advance();
            return (make_bool(false), true);
        }
        if c == 34 {  // '"'
            let s, ok = p.parse_string();
            return (make_string(s), ok);
        }
        if c == 91 {  // '['
            return p.parse_array();
        }
        if c == 123 {  // '{'
            return p.parse_object();
        }
        if c >= 48 && c <= 57 || c == 45 {  // '0'-'9' or '-'
            return p.parse_number();
        }

        return (make_null(), false);
    }

    // === 공개 API ===

    // JSON 문자열 파싱
    func parse(input: string) -> (JsonValue, bool) {
        if len(input) == 0 {
            return (make_null(), false);
        }
        let p = Parser{ input: input, pos: 0, len: len(input) };
        let val, ok = p.parse_value();
        if !ok {
            return (make_null(), false);
        }
        // 파싱 후 남은 텍스트 확인 (선택사항)
        return (val, true);
    }

    // JsonValue를 JSON 문자열로 변환
    func stringify(v: JsonValue) -> string {
        if v.kind == KIND_NULL {
            return "null";
        }
        if v.kind == KIND_BOOL {
            return if v.bool_val { "true" } else { "false" };
        }
        if v.kind == KIND_INT {
            return i64_to_string(v.int_val);
        }
        if v.kind == KIND_FLOAT {
            return f64_to_string(v.float_val);
        }
        if v.kind == KIND_STRING {
            return "\"" + v.str_val + "\"";
        }
        if v.kind == KIND_ARRAY {
            let parts = make([string], 0);
            let i = 0;
            for i = 0; i < len(v.array_vals); i = i + 1 {
                parts.push(stringify(v.array_vals[i]));
            }
            return "[" + join(parts, ",") + "]";
        }
        if v.kind == KIND_OBJECT {
            let parts = make([string], 0);
            let i = 0;
            for i = 0; i < len(v.object_keys); i = i + 1 {
                let kv = "\"" + v.object_keys[i] + "\":" + stringify(v.object_vals[i]);
                parts.push(kv);
            }
            return "{" + join(parts, ",") + "}";
        }
        return "";
    }

    // JsonValue를 들여쓰기와 함께 JSON 문자열로 변환
    func pretty(v: JsonValue) -> string {
        // 간단한 구현: stringify와 동일 (부동소수점 제외하고는 실제 들여쓰기 미구현)
        return stringify(v);
    }

    // JsonValue에서 점 경로로 값 추출
    // 예: get(v, "a.b.c") → v.a.b.c
    func get(v: JsonValue, path: string) -> (JsonValue, bool) {
        if len(path) == 0 {
            return (v, true);
        }
        if v.kind != KIND_OBJECT {
            return (make_null(), false);
        }

        // Note: 점 기준 분할 필요 (문자열 처리 미구현)
        // 여기서는 전체 path를 키로 사용 (임시)
        let i = 0;
        for i = 0; i < len(v.object_keys); i = i + 1 {
            if v.object_keys[i] == path {
                return (v.object_vals[i], true);
            }
        }
        return (make_null(), false);
    }

    // 두 JsonValue 병합 (모두 object여야 함)
    func merge(a: JsonValue, b: JsonValue) -> (JsonValue, bool) {
        if a.kind != KIND_OBJECT || b.kind != KIND_OBJECT {
            return (b, false);
        }

        let result_keys = make([string], 0);
        let result_vals = make([JsonValue], 0);

        // a의 모든 키-값 복사
        let i = 0;
        for i = 0; i < len(a.object_keys); i = i + 1 {
            result_keys.push(a.object_keys[i]);
            result_vals.push(a.object_vals[i]);
        }

        // b의 키-값 추가 또는 덮어쓰기
        for i = 0; i < len(b.object_keys); i = i + 1 {
            let key = b.object_keys[i];
            let val = b.object_vals[i];
            let found = false;
            let j = 0;
            for j = 0; j < len(result_keys); j = j + 1 {
                if result_keys[j] == key {
                    result_vals[j] = val;
                    found = true;
                    j = len(result_keys);  // break
                }
            }
            if !found {
                result_keys.push(key);
                result_vals.push(val);
            }
        }

        return (JsonValue{
            kind: KIND_OBJECT, bool_val: false, int_val: 0, float_val: 0.0, str_val: "",
            array_vals: make([JsonValue], 0), object_keys: result_keys, object_vals: result_vals,
        }, true);
    }

    // === 헬퍼 함수 ===

    @inline
    func i64_to_string(n: i64) -> string {
        if n == 0 { return "0"; }
        if n == 1 { return "1"; }
        if n == 2 { return "2"; }
        if n < 0 { return "-" + i64_to_string(-n); }
        return "?";
    }

    // 배열을 구분자로 연결
    func join(parts: [string], sep: string) -> string {
        if len(parts) == 0 {
            return "";
        }
        let result = parts[0];
        let i = 1;
        for i = 1; i < len(parts); i = i + 1 {
            result = result + sep + parts[i];
        }
        return result;
    }
}

