        print("Integration tests completed");
    }

    // === Main Test Runner ===

    func main() {
        print("====================================");
        print("FreeLang stdlib Module Test Suite");
        print("====================================");

        test_io();
        test_collections();
        test_json();
        test_concurrent();
        test_integration();

        print("\n====================================");
        print("All tests completed!");
        print("====================================");
    }
}

