        // 테스트 6: contains
        let has = collections.contains(data1, 2);
        let r6 = assert_true(has, "collections.contains");
        print_result(r6);

        // 테스트 7: filter_gt
        let filtered = collections.filter_gt(data2, 1);
        let r7 = assert_equal_i64(i64(len(filtered)), 2, "collections.filter_gt");
        print_result(r7);

        // 테스트 8: sort_asc
        let sorted = collections.sort_asc(data2);
        let first = if len(sorted) > 0 { sorted[0] } else { 0 };
        let r8 = assert_equal_i64(first, 1, "collections.sort_asc");
        print_result(r8);

        // 테스트 9: take
        let taken = collections.take(data1, 2);
        let r9 = assert_equal_i64(i64(len(taken)), 2, "collections.take");
        print_result(r9);

        // 테스트 10: skip
        let skipped = collections.skip(data1, 1);
        let r10 = assert_equal_i64(i64(len(skipped)), 2, "collections.skip");
        print_result(r10);

        print("Collections tests completed");
    }

    // === json 모듈 테스트 ===

    func test_json() {
        print("\n=== JSON Module Tests ===");

        // 테스트 1: make_null
        let v1 = json.make_null();
        let r1 = assert_equal_i64(i64(v1.kind), 0, "json.make_null");
        print_result(r1);

        // 테스트 2: make_int
        let v2 = json.make_int(42);
        let r2 = assert_equal_i64(v2.int_val, 42, "json.make_int");
        print_result(r2);

        // 테스트 3: make_string
        let v3 = json.make_string("hello");
        let r3 = assert_true(v3.str_val == "hello", "json.make_string");
        print_result(r3);

        // 테스트 4: stringify int
        let s1 = json.stringify(v2);
        let r4 = assert_true(len(s1) > 0, "json.stringify int");
        print_result(r4);

        // 테스트 5: stringify string
        let s2 = json.stringify(v3);
        let r5 = assert_true(len(s2) > 0, "json.stringify string");
        print_result(r5);

        // 테스트 6: parse null (간단함)
        let pv1, ok1 = json.parse("null");
        let r6 = assert_equal_i64(i64(pv1.kind), 0, "json.parse null");
        print_result(r6);

        // 테스트 7: parse true
        let pv2, ok2 = json.parse("true");
        let r7 = assert_true(ok2, "json.parse true");
        print_result(r7);

        // 테스트 8: merge
        let a = json.make_int(1);
        let b = json.make_int(2);
        let merged, ok3 = json.merge(a, b);
        let r8 = assert_true(ok3, "json.merge");
        print_result(r8);

        print("JSON tests completed");
    }

    // === concurrent 모듈 테스트 ===

    func test_concurrent() {
        print("\n=== Concurrent Module Tests ===");

        // 테스트 1: chan_new
        let ch = concurrent.chan_new(10);
        let r1 = assert_equal_i64(i64(ch.capacity), 10, "concurrent.chan_new capacity");
        print_result(r1);

        // 테스트 2: chan_is_empty
        let is_empty = ch.chan_is_empty();
        let r2 = assert_true(is_empty, "concurrent.chan_is_empty");
        print_result(r2);

        // 테스트 3: chan_send
        let ok1 = ch.chan_send(42);
        let r3 = assert_true(ok1, "concurrent.chan_send");
        print_result(r3);

        // 테스트 4: chan_len
        let len_val = ch.chan_len();
        let r4 = assert_equal_i64(i64(len_val), 1, "concurrent.chan_len after send");
        print_result(r4);

        // 테스트 5: chan_recv
        let msg, ok2 = ch.chan_recv();
        let r5 = assert_equal_i64(msg, 42, "concurrent.chan_recv");
        print_result(r5);

        // 테스트 6: chan_is_empty after recv
        let is_empty2 = ch.chan_is_empty();
        let r6 = assert_true(is_empty2, "concurrent.chan_is_empty after recv");
        print_result(r6);

        // 테스트 7: actor_new
        let actor = concurrent.actor_new(1, 10);
        let r7 = assert_equal_i64(i64(actor.id), 1, "concurrent.actor_new id");
        print_result(r7);

        // 테스트 8: actor_send
        let ok3 = actor.actor_send(100);
        let r8 = assert_true(ok3, "concurrent.actor_send");
        print_result(r8);

        // 테스트 9: actor_recv
        let val, ok4 = actor.actor_recv();
        let r9 = assert_equal_i64(val, 100, "concurrent.actor_recv");
        print_result(r9);

        // 테스트 10: scheduler_new
        let sched = concurrent.scheduler_new();
        let r10 = assert_equal_i64(i64(sched.next_id), 1, "concurrent.scheduler_new");
        print_result(r10);

        print("Concurrent tests completed");
    }

    // === 통합 테스트 ===

    func test_integration() {
        print("\n=== Integration Tests ===");

        // 테스트 1: collections + io 연동
        // 파일 경로 조합
        let dir = "/data";
        let file = "results.json";
        let full_path = io.join_path(dir, file);
        let r1 = assert_true(len(full_path) > 0, "io.join_path → path string");
        print_result(r1);

        // 테스트 2: collections + json 연동
        // 배열 생성 및 JSON 변환
        let data = [i64]{10, 20, 30, 40, 50};
        let sum_val = collections.sum(data);
        let json_val = json.make_int(sum_val);
        let json_str = json.stringify(json_val);
        let r2 = assert_true(len(json_str) > 0, "collections.sum → json.stringify");
        print_result(r2);

        // 테스트 3: concurrent + io 연동
        // 채널로 메시지 전달 후 경로 처리
        let ch = concurrent.chan_new(5);
        ch.chan_send(99);
        let msg, ok = ch.chan_recv();
        let test_path = io.join_path("/test", i64_to_string(msg) + ".dat");
        let r3 = assert_true(ok && len(test_path) > 0, "concurrent.chan ↔ io.join_path");
        print_result(r3);

        // 테스트 4: 모든 모듈 연동
        // data → collections(sum) → json(stringify) → io(path)
        let numbers = [i64]{1, 2, 3, 4, 5};
        let total = collections.sum(numbers);
        let jv = json.make_int(total);
        let js = json.stringify(jv);
        let pathname = io.join_path("/output", "result_" + js + ".json");
        let r4 = assert_true(len(pathname) > 0, "all modules: collect→json→io");
        print_result(r4);

        print("Integration tests completed");
    }

    // === Main Test Runner ===

    func main() {
        print("====================================");
        print("FreeLang stdlib Module Test Suite");
        print("====================================");

        test_io();
        test_collections();
        test_json();
        test_concurrent();
        test_integration();

        print("\n====================================");
        print("All tests completed!");
        print("====================================");
    }
}

